function validate(input) {
  const [{ Candidates = [], Rounds = [] }] = input;
  const ids = new Set(), rounds = new Set();
  for (const [id, , years, interview] of Candidates) {
    if (id === null) return 'Every candidate needs a candidate_id.';
    if (ids.has(id)) return `candidate_id ${id} appears twice in Candidates.`;
    ids.add(id);
    if (years === null || years < 0) return `Candidate ${id} needs a non-negative years_of_exp.`;
    if (interview === null) return `Candidate ${id} needs an interview_id.`;
  }
  for (const [interview, round, score] of Rounds) {
    if (interview === null || round === null) return 'Every round needs an interview_id and a round_id.';
    const key = `${interview}/${round}`;
    if (rounds.has(key)) return `Round ${round} of interview ${interview} appears twice.`;
    rounds.add(key);
    if (score === null || score < 0) return `Round ${round} of interview ${interview} needs a non-negative score.`;
  }
  return null;
}

