function generate(rand, size) {
  const names = ['Atticus', 'Ruben', 'Aliza', 'Alfredo', 'Mina', 'Tomas', 'Ana'];
  const small = size === 'small';
  const Candidates = [], Rounds = [];
  const count = small ? Math.floor(rand() * 6) : 500;
  // Scores of 3 to 9 over 2 to 4 rounds make totals land near the threshold of 15.
  const addRounds = (interview, most) => {
    const n = Math.floor(rand() * (most + 1));
    for (let round = 1; round <= n; round++) Rounds.push([interview, round, 3 + Math.floor(rand() * 7)]);
  };
  for (let i = 1; i <= count; i++) {
    const years = small ? [0, 1, 2, 2, 3, 6, 10][Math.floor(rand() * 7)] : Math.floor(rand() * 12);
    Candidates.push([i * 3, names[Math.floor(rand() * names.length)], years, 100 + i]);
    if (small) { if (Rounds.length < 8) addRounds(100 + i, Math.min(4, 8 - Rounds.length)); }
    else addRounds(100 + i, 4);
  }
  // Sometimes an interview whose candidate is not listed.
  if (rand() < 0.3 && (!small || Rounds.length < 7)) addRounds(999, small ? 8 - Rounds.length : 3);
  return [{ Candidates, Rounds }];
}
